/* Start here entry for room-acoustics (demos/lib/starthere/room-acoustics.js). Generated by tools/activities.py from curriculum/start-here.json:
   edit the data, not this file. demos/lib/starthere.js loads it. */
window.VDStartHere && VDStartHere({"q":"How long does one clap keep sounding in a bare brick room?","q_es":"¿Cuánto tiempo sigue sonando un aplauso en una sala desnuda de ladrillo?","setup":"","do":"A 9 m by 7 m by 3 m room with painted brick walls and a concrete floor, in the 500 Hz band. Guess how long a clap takes to die away, then press <b>Clap</b> and read <b>Measured T</b>, the time for the sound to fall by 60 dB. Press <b>Add absorbing panels</b> (14.4 m² of foam on 222 m² of surface), decide how much T will change, and clap again.","do_es":"Una sala de 9 m por 7 m por 3 m con paredes de ladrillo pintado y piso de concreto, en la banda de 500 Hz. Adivina cuánto tarda un aplauso en apagarse, luego presiona <b>Aplaudir</b> y lee <b>T medido</b>, el tiempo que tarda el sonido en bajar 60 dB. Presiona <b>Agregar paneles absorbentes</b> (14.4 m² de espuma en 222 m² de superficie), decide cuánto cambiará T y aplaude otra vez.","see":"4.75 s in the bare room, close to Sabine's 0.161 V/A = 4.81 s: brick sends back 98% of the sound energy at every bounce. The panels cover only 14.4 m² of the 222 m² but raise the absorption A from 6.33 m² to 17.99 m², and T falls to 1.62 s, about a third.","see_es":"4.75 s en la sala desnuda, cerca de los 4.81 s de Sabine, 0.161 V/A: el ladrillo devuelve el 98% de la energía del sonido en cada rebote. Los paneles cubren solo 14.4 m² de los 222 m² pero suben la absorción A de 6.33 m² a 17.99 m², y T baja a 1.62 s, más o menos la tercera parte.","explore":[{"setup":"set=sL~9!sW~7!sH~3!sN~20!sR~3!labBlind~0!g%3AwallSeg~panels!g%3AbandSeg~125","do":"The same twenty panels, now in the <b>125</b> Hz <b>Octave band</b>. Decide whether foam stops a low boom as well as it stops 500 Hz, then press <b>Clap</b> and read <b>Measured T</b>.","do_es":"Los mismos veinte paneles, ahora en la <b>Banda de octava</b> de <b>125</b> Hz. Decide si la espuma detiene un retumbo grave tan bien como detiene los 500 Hz, luego presiona <b>Aplaudir</b> y lee <b>T medido</b>.","see":"7.86 s, against 1.62 s at 500 Hz. The foam absorbs 83% of the sound that hits it at 500 Hz but only 12% at 125 Hz: soft materials take out highs well and lows poorly, so a treated room can still boom.","see_es":"7.86 s, contra 1.62 s a 500 Hz. La espuma absorbe el 83% del sonido que le llega a 500 Hz pero solo el 12% a 125 Hz: los materiales blandos quitan bien los agudos y mal los graves, así que una sala tratada todavía puede retumbar."},{"setup":"set=sL~8!sW~6!sH~5!sD~0.3!sR~1!labBlind~0!g%3AwallSeg~wedges!g%3Apresets~anechoic!g%3AmodeSeg~level","do":"<b>Anechoic chamber</b>: wedges on all six surfaces, a steady 10 mW source and the microphone 1.00 m away. Read <b>Level at the microphone</b>, predict it at 2 m and 4 m, then drag <b>Microphone distance r</b> to 2.00 m and 4.00 m and read it again.","do_es":"<b>Cámara anecoica</b>: cuñas en las seis superficies, una fuente fija de 10 mW y el micrófono a 1.00 m. Lee <b>Nivel en el micrófono</b>, predícelo a 2 m y a 4 m, luego arrastra <b>Distancia del micrófono r</b> a 2.00 m y a 4.00 m y vuelve a leerlo.","see":"89.2, 83.1 and 77.1 dB: 6 dB less for each doubling of distance, the 1/r² of open air, because nothing comes back from the walls. In the bare brick room the same doublings cost less than 1 dB each, since reflected sound fills the room.","see_es":"89.2, 83.1 y 77.1 dB: 6 dB menos cada vez que se duplica la distancia, el 1/r² del aire libre, porque nada regresa de las paredes. En la sala desnuda de ladrillo esas mismas duplicaciones bajan menos de 1 dB cada una, porque el sonido reflejado llena la sala."},{"setup":"set=sL~8!sW~6!sH~5!sD~0.3!sR~1!labBlind~0!g%3AwallSeg~wedges!g%3Apresets~cutoff!g%3AmodeSeg~level!g%3AbandSeg~125","do":"<b>Below the cutoff</b>: the same chamber at 125 Hz, where the wavelength, 2.75 m, is more than four times the 0.3 m wedge depth. Read <b>Level at the microphone</b> at 1.00, 2.00 and 4.00 m and compare the drops with the 6 dB at 500 Hz.","do_es":"<b>Por debajo del corte</b>: la misma cámara a 125 Hz, donde la longitud de onda, 2.75 m, es más de cuatro veces la profundidad de 0.3 m de las cuñas. Lee <b>Nivel en el micrófono</b> a 1.00, 2.00 y 4.00 m y compara las bajadas con los 6 dB a 500 Hz.","see":"89.7, 84.7 and 80.4 dB: only 5.0 and then 4.3 dB per doubling. Wedges this short reflect long waves (their cutoff is c/4d = 286 Hz), so echoes add to the direct sound. A chamber for low frequencies needs deeper wedges.","see_es":"89.7, 84.7 y 80.4 dB: solo 5.0 y luego 4.3 dB por duplicación. Unas cuñas tan cortas reflejan las ondas largas (su corte es c/4d = 286 Hz), así que los ecos se suman al sonido directo. Una cámara para frecuencias bajas necesita cuñas más profundas."}]});
